#### Interactive leaflet map of preliminary canopy severity predictions
####
#### Displays burn unit boundaries alongside pixel-level model outputs
#### generated by 0.5_prelim_prediction.R.
####
#### Layers (all toggle-able):
####   - Burn boundaries     : always visible, polygon outlines with popups
####   - Predicted class     : categorical raster (Closed / Open / Early Seral)
####   - P(Closed)           : continuous probability raster
####   - P(Open)             : continuous probability raster
####   - P(Early Seral)      : continuous probability raster
####
#### Prerequisites
####   output/prelim_model/unit_predictions/mosaics/mosaic_*.tif  (from 0.5)
####   output/prelim_model/unit_predictions/unit_summary.csv       (from 0.5)
####   rx.shp available in session OR shp path below is correct

library(tidyverse)
library(sf)
library(terra)
library(raster)   # needed for addRasterImage conversion
library(leaflet)

# ---- 0. Paths ----------------------------------------------------------------

pred_dir   <- "output/prelim_model/unit_predictions"
mosaic_dir <- file.path(pred_dir, "mosaics")
shp_path   <- "data/from_jean/080726_update/Rxb units and canopy layers/rxbmodel/1burn_cnpy.shp"

# ---- 1. Load mosaics ---------------------------------------------------------

mos_class  <- rast(file.path(mosaic_dir, "mosaic_pred_class.tif"))
mos_closed <- rast(file.path(mosaic_dir, "mosaic_prob_Closed.tif"))
mos_open   <- rast(file.path(mosaic_dir, "mosaic_prob_Open.tif"))
mos_es     <- rast(file.path(mosaic_dir, "mosaic_prob_EarlySeral.tif"))

# ---- 2. Burn boundaries + unit summary ---------------------------------------
# Uses session rx.pred if present (from 0.5), otherwise rebuilds from files.


u_summary <- read.csv(file.path(pred_dir, "unit_summary.csv"))
raw_shp   <- sf::read_sf(shp_path)

bounds_sf <- raw_shp |>
  filter(burn_name %in% u_summary$burn_name) |>
  st_transform(4326)


# ---- 3. Reproject rasters to WGS84 ------------------------------------------

mos_class_wgs  <- project(mos_class,  "EPSG:4326")
mos_closed_wgs <- project(mos_closed, "EPSG:4326")
mos_open_wgs   <- project(mos_open,   "EPSG:4326")
mos_es_wgs     <- project(mos_es,     "EPSG:4326")

# Convert to raster-package objects for addRasterImage
# r_class  <- as(mos_class_wgs,  "Raster")
# r_closed <- as(mos_closed_wgs, "Raster")
# r_open   <- as(mos_open_wgs,   "Raster")
# r_es     <- as(mos_es_wgs,     "Raster")

# ---- 4. Color palettes -------------------------------------------------------

# pred_class: integer codes 1 = Closed, 2 = Open, 3 = Early Seral
class_pal <- colorFactor(
  palette  = c("forestgreen", "goldenrod3", "firebrick2"),
  levels   = c(1, 2, 3),
  na.color = "transparent"
)

# Probability layers (0–1)
pal_closed <- colorNumeric("Greens", domain = c(0, 1), na.color = "transparent")
pal_open   <- colorNumeric("YlOrBr", domain = c(0, 1), na.color = "transparent")
pal_es     <- colorNumeric("Reds",   domain = c(0, 1), na.color = "transparent")

# Polygon fill for dominant class (used only when raster layers are hidden)
dom_pal <- colorFactor(
  palette  = c("forestgreen", "goldenrod3", "firebrick2"),
  domain   = c("Closed", "Open", "Early Seral"),
  na.color = "grey80"
)

# Severity_1 palette: 0 = Closed, 1 = Open, 2 = Early Seral; 3/91 → transparent
sev_pal <- colorFactor(
  palette  = c("forestgreen", "goldenrod3", "firebrick2"),
  levels   = c(0L, 1L, 2L),
  na.color = "transparent"
)

# ---- 5. Popup content --------------------------------------------------------

popup_html <- sprintf(
  "<b>%s</b><br>
   Dominant class: <b>%s</b><br>
   P(Closed) = %.2f<br>
   P(Open) = %.2f<br>
   P(Early Seral) = %.2f<br>
   Pixels predicted: %s",
  bounds_sf$burn_name,
  bounds_sf$dominant_class,
  bounds_sf$mean_prob_Closed,
  bounds_sf$mean_prob_Open,
  bounds_sf$mean_prob_EarlySeral,
  format(bounds_sf$n_pixels, big.mark = ",")
)

# ---- 6. Build map ------------------------------------------------------------

leaflet_map <- leaflet() |>

  # Base tiles
  addProviderTiles("Esri.WorldTopoMap",  group = "Topo") |>
  addProviderTiles("Esri.WorldImagery",  group = "Satellite") |>

  # ---- Raster layers ---------------------------------------------------------

  addRasterImage(
    x       = mos_class_wgs,
    colors  = class_pal,
    opacity = 0.75,
    group   = "Predicted class",
    maxBytes = Inf   # raise ceiling for larger mosaics
  ) |>

  addRasterImage(
    x        = mos_closed_wgs,
    colors   = pal_closed,
    opacity  = 0.75,
    group    = "P(Closed)",
    maxBytes = Inf
  ) |>

  addRasterImage(
    x        = mos_open_wgs,
    colors   = pal_open,
    opacity  = 0.75,
    group    = "P(Open)",
    maxBytes = Inf
  ) |>

  addRasterImage(
    x        = mos_es_wgs,
    colors   = pal_es,
    opacity  = 0.75,
    group    = "P(Early Seral)",
    maxBytes = Inf
  ) |>

  # ---- Burn boundaries (on top so labels/popups are always accessible) -------

  addPolygons(
    data        = bounds_sf,
    fillColor   = ~sev_pal(ifelse(Severity_1 %in% c(0L, 1L, 2L), Severity_1, NA_integer_)),
    fillOpacity = 0.5,
    color       = "white",
    weight      = 2,
    label       = ~burn_name,
    group       = "Burn boundaries"
  ) |>

  # ---- Legends ---------------------------------------------------------------

  addLegend(
    position = "bottomright",
    colors   = c("#228B22", "#CD950C", "#EE2C2C"),
    labels   = c("Closed", "Open", "Early Seral"),
    title    = "Burn severity (Severity_1)",
    group    = "Burn boundaries"
  ) |>

  addLegend(
    position = "bottomright",
    colors   = c("#228B22", "#CD950C", "#EE2C2C"),
    labels   = c("Closed", "Open", "Early Seral"),
    title    = "Predicted class",
    group    = "Predicted class"
  ) |>

  addLegend(
    pal      = pal_closed,
    values   = c(0, 1),
    title    = "P(Closed)",
    position = "bottomright",
    group    = "P(Closed)"
  ) |>

  addLegend(
    pal      = pal_open,
    values   = c(0, 1),
    title    = "P(Open)",
    position = "bottomright",
    group    = "P(Open)"
  ) |>

  addLegend(
    pal      = pal_es,
    values   = c(0, 1),
    title    = "P(Early Seral)",
    position = "bottomright",
    group    = "P(Early Seral)"
  ) |>

  # ---- Layer control ---------------------------------------------------------

  addLayersControl(
    baseGroups    = c("Topo", "Satellite"),
    overlayGroups = c(
      "Burn boundaries",
      "Predicted class",
      "P(Closed)", "P(Open)", "P(Early Seral)"
    ),
    options = layersControlOptions(collapsed = FALSE)
  ) |>

  # Show only predicted class by default
  hideGroup(c("P(Closed)", "P(Open)", "P(Early Seral)"))

leaflet_map

# ---- 7. Save widget ----------------------------------------------------------

out_html <- "output/prelim_model/leaflet/apps_rx_preds_PRELIM.html"
htmlwidgets::saveWidget(leaflet_map, file = normalizePath(out_html, mustWork = FALSE))
message("Map saved to: ", out_html)
